//! 🕰️ Authenticated history inspection and explicit maintenance use the ordinary cancellable worker.
use super::*;
use semio_framework_ui_tui_widgets::widget::InputState;
impl<H:SourceWindowPort> View<'_,H>{
 pub fn next_history_page(&mut self,index:usize){if self.source_job.is_some(){self.effects.push(Effect::Notice(Some(self.text().source_busy.as_str().into())));return;}let Body::Files(files)=self.port.window(index).body else{return;};match files.next_page(){Ok(request)=>self.request_source(index,request),Err(error)=>self.effects.push(Effect::Notice(Some(self.text().source_browser_error(error,None))))}}
 pub(super) fn adopt_history_result(&mut self,tui:&mut Tui,index:usize,response:Response){match response{
  Response::HistoryPage(page)=>{if let Body::Files(files)=self.port.window_mut(index).body{files.adopt_page(page);}self.paint_files(tui,index);let keys=[("next","next-history-page"),("inspect","inspect-history"),("reconcile","reconcile-history"),("archive","archive-history")].map(|(name,id)|(name,self.context.keymap.keys_label(dashboard_preferences::keymap::Scope::Prefix,id).unwrap_or_default()));let inspection=match self.port.window(index).body{Body::Files(files)=>files.inspection.as_ref(),_=>None};self.effects.push(Effect::Notice(Some(self.text().source_history_notice(inspection,&keys.each_ref().map(|(name,key)|(*name,key.as_str()))))));},
  Response::HistoryInspected(action,expected)=>{if let Body::Files(files)=self.port.window_mut(index).body{files.inspection=Some(expected.clone());}if let Some(action)=action{let form=HistoryForm{action,expected,busy:false};if let Err(error)=form.confirmation(){self.effects.push(Effect::Notice(Some(self.text().source_browser_error(error,None))));return;}let input=InputState::new(self.text().source_name.as_str().to_owned());if let Body::Files(files)=self.port.window_mut(index).body{files.history_form=Some(form);files.form=None;}if let Some(widget)=tui.scene.node_mut(self.port.window(index).list).widget(){*widget=WidgetState::Input(input);}tui.set_focus(Some(self.port.window(index).list));self.effects.push(Effect::Notice(None));}else{self.request_source(index,Request::HistoryPage(None));}},
  Response::HistoryChanged(_,expected)=>{if let Body::Files(files)=self.port.window_mut(index).body{files.inspection=Some(expected);files.history_form=None;}self.request_source(index,Request::HistoryPage(None));},_=>unreachable!()}}
 pub(super) fn history_key(&mut self,tui:&mut Tui,index:usize,key:&KeyEvent)->bool{let Some(form)=(match self.port.window(index).body{Body::Files(files)=>files.history_form.as_ref(),_=>None})else{return false;};if key.key==Key::Esc{if form.busy{self.cancel_source();}else{if let Body::Files(files)=self.port.window_mut(index).body{files.history_form=None;}self.paint_files(tui,index);self.effects.push(Effect::Notice(None));}return true;}if form.busy{return true;}if key.key==Key::Enter{let value=match &tui.scene.node(self.port.window(index).list).content{NodeContent::Widget(WidgetState::Input(input))=>input.value.clone(),_=>return true};let request=match self.port.window(index).body{Body::Files(files)=>files.prepare_history(&value),_=>return true};match request{Ok(request)=>{if let Body::Files(files)=self.port.window_mut(index).body{files.history_form.as_mut().unwrap().busy=true;}self.request_source(index,request);},Err(error)=>self.effects.push(Effect::Notice(Some(self.text().source_browser_error(error,None))))}return true;}self.source_form_key(tui,index,key);true}
 pub(super) fn history_paste(&mut self,tui:&mut Tui,index:usize,text:&str)->bool{let Some(form)=(match self.port.window(index).body{Body::Files(files)=>files.history_form.as_ref(),_=>None})else{return false;};if form.busy{return true;}self.source_form_paste(tui,index,text);true}
}
